package com.ruoyi.hexu;
import org.springframework.web.bind.annotation.*;
import java.util.*;
import static com.ruoyi.hexu.HexuStore.*;
import static com.ruoyi.hexu.HexuAppController.ok;
@RestController @RequestMapping("/hexu/admin")
public class HexuAdminController {
    private final HexuIdentity auth;private final HexuStore db;private final HexuCatalogService catalog;private final HexuOrderService orders;private final HexuFinanceService finance;private final HexuWorkflowService workflow;private final HexuCommands commands;
    public HexuAdminController(HexuIdentity auth,HexuStore db,HexuCatalogService catalog,HexuOrderService orders,HexuFinanceService finance,HexuWorkflowService workflow,HexuCommands commands){this.auth=auth;this.db=db;this.catalog=catalog;this.orders=orders;this.finance=finance;this.workflow=workflow;this.commands=commands;}
    @GetMapping("/catalog-settings") public Object catalogSettings(@RequestParam long shopId){return ok(new HexuProductData(db).settings(auth.admin(),shopId));}
    @GetMapping("/shops") public Object shops(){Actor a=auth.admin();return ok(a.platform?db.jdbc().queryForList("select * from hx_shop order by id"):db.jdbc().queryForList("select s.* from hx_shop s join hx_staff u on u.shop_id=s.id where u.user_id=? order by s.id",a.id));}
    @GetMapping("/dashboard") public Object dashboard(@RequestParam long shopId){return ok(workflow.dashboard(auth.admin(),shopId));}
    @GetMapping("/products") public Object products(@RequestParam long shopId){return ok(catalog.products(auth.admin(),shopId,true));}
    @GetMapping("/orders") public Object orders(@RequestParam long shopId){return ok(orders.list(auth.admin(),shopId,true));}
    @GetMapping("/orders/{id}") public Object order(@PathVariable String id){return ok(orders.detail(auth.admin(),id,true));}
    @GetMapping("/resources/{resource}") public Object resources(@PathVariable String resource,@RequestParam long shopId){return ok(workflow.managementList(auth.admin(),shopId,resource));}
    @GetMapping("/documents/{kind}") public Object documents(@PathVariable String kind,@RequestParam long shopId){return ok(workflow.list(auth.admin(),shopId,kind,true));}
    @GetMapping("/rules") public Object rules(){db.platform(auth.admin());return ok(db.jdbc().queryForList("select * from hx_rule order by effective_at desc"));}
    @PostMapping("/commands/{operation}") public Object command(@PathVariable String operation,@RequestHeader("Idempotency-Key")String key,@RequestBody Map<String,Object>b){Actor a=auth.admin();return ok(commands.execute(a,key,operation,b,()->dispatch(a,operation,b,catalog,orders,finance,workflow)));}
    @GetMapping("/statements/{id}/lines") public Object statementLines(@PathVariable String id,@RequestParam long shopId){return HexuAppController.ok(workflow.statementLines(auth.admin(),shopId,id));}
    static Object dispatch(Actor a,String operation,Map<String,Object>b,HexuCatalogService catalog,HexuOrderService orders,HexuFinanceService finance,HexuWorkflowService workflow){long shop=number(b,"shopId");switch(operation){case "staff-assign":return workflow.assignStaff(a,shop,b);case "marketing-preview":return orders.marketingPreview(a,shop,b);case "reconcile-import":return workflow.importStatement(a,shop,b);case "reconcile-recheck":return workflow.recheckStatement(a,str(b,"id"));case "adjustment-propose":return workflow.proposeAdjustment(a,str(b,"id"),b);case "adjustment-review":return workflow.reviewAdjustment(a,str(b,"id"),b);case "assessment-run":return workflow.runDowngrades(a,shop);case "settlement-preview":return orders.simulate(a,shop,b);case "export-audit":return workflow.exportAudit(a,shop,b);case "stock-warning":return catalog.warning(a,shop,b);case "sku-status":return catalog.status(a,shop,b);case "report-create":return workflow.createReport(a,shop,b);case "point-freeze-review":return workflow.reviewPointFreeze(a,str(b,"id"),b);case "catalog-settings-save":return workflow.saveCatalogSettings(a,shop,b);case "sku-box-rules":return catalog.boxRules(a,shop,b);case "sku-save":return catalog.saveSku(a,shop,b);case "stock-adjust":return catalog.stockAdjust(a,shop,b);case "ship":return orders.ship(a,str(b,"id"),b);case "withdraw-review":return finance.reviewWithdrawal(a,str(b,"id"),bool(b,"approve"),str(b,"reason"));case "refund-review":return finance.refundReview(a,str(b,"id"),b);case "exchange-ship":return finance.exchangeShip(a,str(b,"id"),b);case "return-inspect":return finance.inspect(a,str(b,"id"),b);case "document-save":return workflow.save(a,shop,str(b,"kind"),b,true);case "document-review":return workflow.review(a,str(b,"id"),b);case "rule-create":return workflow.rule(a,b);default:throw new BusinessException("未知管理操作");}}
}
